include '../includes/session.php';include '../database/config.php';include '../includes/helpers.php';require_once '../services/CertificateService.php';requireAdmin();requirePermission('certificates.manage');$id=(int)($_GET['id']??0);$stmt=$conn->prepare("SELECT certificate_number,pdf_path,certificate_hash,status FROM certificate_issuances WHERE certificate_id=?");$stmt->bind_param('i',$id);$stmt->execute();$c=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$c||empty($c['pdf_path'])||!in_array($c['status'],['issued','released','revoked','reissued'],true)){http_response_code(404);exit('Certificate PDF not found.');}$root=realpath(dirname(__DIR__).DIRECTORY_SEPARATOR.'uploads'.DIRECTORY_SEPARATOR.'issued_certificates');$path=realpath(dirname(__DIR__).DIRECTORY_SEPARATOR.str_replace('/',DIRECTORY_SEPARATOR,$c['pdf_path']));if(!$root||!$path||strpos($path,$root.DIRECTORY_SEPARATOR)!==0||!is_file($path)){http_response_code(404);exit('Certificate PDF not found.');}if(!hash_equals((string)$c['certificate_hash'],hash_file('sha256',$path))){http_response_code(409);exit('Certificate integrity check failed.');}(new CertificateService($conn,dirname(__DIR__)))->logDownload($id,(int)$_SESSION['user_id']);header('Content-Type: application/pdf');header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="'.preg_replace('/[^A-Za-z0-9._-]/','_',$c['certificate_number']).'.pdf"');header('X-Content-Type-Options: nosniff');readfile($path);
